-- Fenced, database-clock worker transitions. External executors receive only
-- the claim/result entry points below; aggregate state remains private.
CREATE INDEX membership_access_steps_expired_lease_idx ON control_plane.membership_access_steps(lease_expires_at) WHERE state='leased';

CREATE FUNCTION control_plane.recompute_membership_access_operation(p_operation uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane AS $$
DECLARE o membership_access_operations%ROWTYPE; blocked_prereq boolean; blocked_work boolean; all_done boolean; local_ok boolean; now_at timestamptz; BEGIN
 SELECT * INTO o FROM membership_access_operations WHERE id=p_operation FOR UPDATE; IF NOT FOUND OR o.state='completed' THEN RETURN; END IF;
 now_at:=clock_timestamp();
 SELECT EXISTS(SELECT 1 FROM membership_access_steps WHERE operation_id=o.id AND step_kind LIKE '%_prerequisite' AND state='blocked'),EXISTS(SELECT 1 FROM membership_access_steps WHERE operation_id=o.id AND step_kind NOT LIKE '%_prerequisite' AND state='blocked'),NOT EXISTS(SELECT 1 FROM membership_access_steps WHERE operation_id=o.id AND state<>'succeeded'),EXISTS(SELECT 1 FROM membership_access_states s WHERE s.mapping_id=o.mapping_id AND s.barrier_state='suspended' AND s.current_operation_id=o.id AND s.revision=o.transition_revision) AND o.local_enforced_at IS NOT NULL AND EXISTS(SELECT 1 FROM security_audit_events a WHERE a.operation_id=o.id AND a.mapping_id=o.mapping_id AND a.event_type='membership_access_local_enforced' AND a.outcome='success' AND a.occurred_at=o.local_enforced_at AND a.source_id IS NOT NULL) INTO blocked_prereq,blocked_work,all_done,local_ok;
 IF all_done AND local_ok THEN
  UPDATE membership_access_operations SET state='completed',completed_at=now_at,blocked_code=NULL WHERE id=o.id AND state<>'completed';
  INSERT INTO security_audit_events(id,event_type,mapping_id,outcome,reason,occurred_at,operation_id) SELECT gen_random_uuid(),'membership_access_operation_terminal',o.mapping_id,'success','completed',now_at,o.id WHERE NOT EXISTS(SELECT 1 FROM security_audit_events WHERE operation_id=o.id AND event_type='membership_access_operation_terminal');
 ELSIF blocked_prereq THEN UPDATE membership_access_operations SET state='blocked',completed_at=NULL,blocked_code='missing_external_prerequisites' WHERE id=o.id;
 ELSIF blocked_work THEN UPDATE membership_access_operations SET state='blocked',completed_at=NULL,blocked_code='external_step_blocked' WHERE id=o.id;
 ELSE UPDATE membership_access_operations SET state='reconciling',completed_at=NULL,blocked_code=NULL WHERE id=o.id; END IF;
END $$;

CREATE FUNCTION control_plane.claim_membership_access_step(p_owner text,p_step_kinds text[]) RETURNS TABLE(disposition text,claim_attempt_id uuid,step_id uuid,operation_id uuid,mapping_id uuid,transition_revision bigint,step_kind text,lease_generation bigint,lease_token bytea,lease_expires_at timestamptz,mas_target_id uuid,mas_user_id text,matrix_user_id text,room_target_id uuid,room_id text,moderator_user_id text,crypto_capability_id uuid,crypto_capability_version text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane AS $$
DECLARE s membership_access_steps%ROWTYPE; a uuid; now_at timestamptz; BEGIN
 IF p_owner IS NULL OR p_owner !~ '^[a-z][a-z0-9_-]{0,63}$' OR p_step_kinds IS NULL OR cardinality(p_step_kinds)=0 OR array_position(p_step_kinds,NULL) IS NOT NULL OR cardinality(p_step_kinds)<>cardinality(ARRAY(SELECT DISTINCT x FROM unnest(p_step_kinds) x)) OR NOT ((cardinality(p_step_kinds)=2 AND p_step_kinds @> ARRAY['mas_lock','mas_finish_sessions'] AND p_step_kinds <@ ARRAY['mas_lock','mas_finish_sessions']) OR p_step_kinds=ARRAY['room_ban'] OR p_step_kinds=ARRAY['crypto_gate']) THEN RAISE EXCEPTION 'invalid worker capability'; END IF;
 PERFORM pg_advisory_xact_lock_shared(8004);
 SELECT st.* INTO s FROM membership_access_steps st JOIN membership_access_operations o ON o.id=st.operation_id JOIN membership_access_states ms ON ms.mapping_id=o.mapping_id AND ms.current_operation_id=o.id AND ms.revision=o.transition_revision AND ms.barrier_state='suspended' WHERE o.state<>'completed' AND st.step_kind=ANY(p_step_kinds) AND ((st.state IN ('pending','retry_wait') AND COALESCE(st.next_attempt_at,'-infinity')<=clock_timestamp()) OR (st.state='leased' AND st.lease_expires_at<=clock_timestamp())) AND (st.step_kind<>'mas_finish_sessions' OR EXISTS(SELECT 1 FROM membership_access_steps x WHERE x.operation_id=st.operation_id AND x.step_kind='mas_lock' AND x.state='succeeded')) AND (st.step_kind<>'crypto_gate' OR NOT EXISTS(SELECT 1 FROM membership_access_steps x WHERE x.operation_id=st.operation_id AND x.step_kind='room_ban' AND x.state<>'succeeded')) FOR UPDATE OF st SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN; END IF; PERFORM 1 FROM membership_access_operations WHERE id=s.operation_id FOR UPDATE; PERFORM control_plane.recompute_membership_access_operation(s.operation_id);
 now_at:=clock_timestamp();
 IF NOT EXISTS(SELECT 1 FROM membership_access_operations o JOIN membership_access_states ms ON ms.mapping_id=o.mapping_id AND ms.current_operation_id=o.id AND ms.revision=o.transition_revision AND ms.barrier_state='suspended' WHERE o.id=s.operation_id AND o.state<>'completed' AND s.mapping_id=o.mapping_id AND s.transition_revision=o.transition_revision) OR NOT ((s.state IN ('pending','retry_wait') AND COALESCE(s.next_attempt_at,'-infinity')<=now_at) OR (s.state='leased' AND s.lease_expires_at<=now_at)) THEN RETURN; END IF;
 IF s.state='leased' AND s.attempt_count>=8 THEN
  SELECT x.id INTO a FROM membership_access_step_attempts x WHERE x.step_id=s.id AND x.event_kind='claim' AND x.lease_generation=s.lease_generation AND x.lease_token=s.lease_token AND x.owner=s.lease_owner FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'expired lease has no exact claim'; END IF;
  INSERT INTO membership_access_step_attempts(id,step_id,operation_id,mapping_id,transition_revision,event_kind,prior_attempt_id,lease_generation,lease_token,owner,outcome,error_code,created_at) VALUES(gen_random_uuid(),s.id,s.operation_id,s.mapping_id,s.transition_revision,'result',a,s.lease_generation,s.lease_token,s.lease_owner,'blocked','retry_exhausted',now_at);
  UPDATE membership_access_steps SET state='blocked',next_attempt_at=NULL,lease_token=NULL,lease_owner=NULL,lease_expires_at=NULL,error_code='retry_exhausted',confirmed_at=NULL,evidence_fingerprint=NULL WHERE id=s.id; PERFORM control_plane.recompute_membership_access_operation(s.operation_id); RETURN QUERY SELECT 'exhausted',NULL::uuid,s.id,s.operation_id,s.mapping_id,s.transition_revision,s.step_kind,s.lease_generation,NULL::bytea,NULL::timestamptz,s.mas_target_id,NULL::text,NULL::text,s.room_target_id,NULL::text,NULL::text,s.crypto_capability_id,NULL::text; RETURN;
 END IF;
 UPDATE membership_access_steps SET state='leased',attempt_count=s.attempt_count+1,next_attempt_at=NULL,lease_generation=s.lease_generation+1,lease_token=sha256(convert_to(gen_random_uuid()::text,'UTF8')),lease_owner=p_owner,lease_expires_at=now_at+interval '30 seconds',error_code=NULL,confirmed_at=NULL,evidence_fingerprint=NULL WHERE id=s.id RETURNING * INTO s;
 a:=gen_random_uuid(); INSERT INTO membership_access_step_attempts(id,step_id,operation_id,mapping_id,transition_revision,event_kind,lease_generation,lease_token,owner,claimed_at,lease_expires_at,created_at) VALUES(a,s.id,s.operation_id,s.mapping_id,s.transition_revision,'claim',s.lease_generation,s.lease_token,p_owner,now_at,s.lease_expires_at,now_at);
 RETURN QUERY SELECT 'claimed',a,s.id,s.operation_id,s.mapping_id,s.transition_revision,s.step_kind,s.lease_generation,s.lease_token,s.lease_expires_at,s.mas_target_id,m.mas_user_id,m.matrix_user_id,s.room_target_id,r.room_id,r.moderator_user_id,s.crypto_capability_id,c.capability_version FROM membership_access_steps q LEFT JOIN membership_access_mas_targets m ON m.id=q.mas_target_id LEFT JOIN membership_access_room_targets r ON r.id=q.room_target_id LEFT JOIN membership_access_crypto_capabilities c ON c.id=q.crypto_capability_id WHERE q.id=s.id;
END $$;

CREATE FUNCTION control_plane.record_membership_access_step_result(p_claim_attempt_id uuid,p_step_id uuid,p_lease_generation bigint,p_lease_token bytea,p_owner text,p_result text,p_error_code text,p_evidence_fingerprint bytea) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane AS $$
DECLARE s membership_access_steps%ROWTYPE; a membership_access_step_attempts%ROWTYPE; now_at timestamptz; outcome text; code text; BEGIN
 IF p_result IS NULL OR p_result NOT IN ('succeeded','retryable','permanent') OR p_owner IS NULL OR p_owner !~ '^[a-z][a-z0-9_-]{0,63}$' THEN RAISE EXCEPTION 'invalid worker result'; END IF;
 SELECT * INTO s FROM membership_access_steps WHERE id=p_step_id FOR UPDATE; IF NOT FOUND THEN RETURN false; END IF; PERFORM 1 FROM membership_access_operations WHERE id=s.operation_id FOR UPDATE; now_at:=clock_timestamp();
 SELECT * INTO a FROM membership_access_step_attempts WHERE id=p_claim_attempt_id AND step_id=s.id AND event_kind='claim' AND lease_generation=p_lease_generation AND lease_token IS NOT DISTINCT FROM p_lease_token AND owner IS NOT DISTINCT FROM p_owner FOR UPDATE; IF NOT FOUND OR s.state<>'leased' OR s.lease_generation<>p_lease_generation OR s.lease_token IS DISTINCT FROM p_lease_token OR s.lease_owner IS DISTINCT FROM p_owner OR s.lease_expires_at<=now_at OR NOT EXISTS(SELECT 1 FROM membership_access_states ms WHERE ms.mapping_id=s.mapping_id AND ms.barrier_state='suspended' AND ms.current_operation_id=s.operation_id AND ms.revision=s.transition_revision) THEN RETURN false; END IF;
 IF p_result='succeeded' THEN IF p_error_code IS NOT NULL OR p_evidence_fingerprint IS NULL OR octet_length(p_evidence_fingerprint)<>32 THEN RAISE EXCEPTION 'invalid success evidence'; END IF; outcome:='succeeded'; UPDATE membership_access_steps SET state='succeeded',next_attempt_at=NULL,lease_token=NULL,lease_owner=NULL,lease_expires_at=NULL,error_code=NULL,confirmed_at=now_at,evidence_fingerprint=p_evidence_fingerprint WHERE id=s.id; INSERT INTO security_audit_events(id,event_type,mapping_id,outcome,reason,occurred_at,step_id) VALUES(gen_random_uuid(),'membership_access_step_succeeded',s.mapping_id,'success','completed',now_at,s.id);
 ELSE IF p_evidence_fingerprint IS NOT NULL OR p_error_code IS NULL OR p_error_code !~ '^[a-z][a-z0-9_]{0,63}$' THEN RAISE EXCEPTION 'invalid worker error'; END IF; code:=CASE WHEN p_result='retryable' AND s.attempt_count>=8 THEN 'retry_exhausted' ELSE p_error_code END; outcome:=CASE WHEN p_result='retryable' AND s.attempt_count<8 THEN 'retry_wait' ELSE 'blocked' END; UPDATE membership_access_steps SET state=outcome,next_attempt_at=CASE WHEN outcome='retry_wait' THEN now_at+make_interval(secs=>least(300,(2^(attempt_count-1))::int)) ELSE NULL END,lease_token=NULL,lease_owner=NULL,lease_expires_at=NULL,error_code=code,confirmed_at=NULL,evidence_fingerprint=NULL WHERE id=s.id; END IF;
 INSERT INTO membership_access_step_attempts(id,step_id,operation_id,mapping_id,transition_revision,event_kind,prior_attempt_id,lease_generation,lease_token,owner,outcome,error_code,evidence_fingerprint,created_at) VALUES(gen_random_uuid(),s.id,s.operation_id,s.mapping_id,s.transition_revision,'result',a.id,p_lease_generation,p_lease_token,p_owner,outcome,CASE WHEN outcome='succeeded' THEN NULL ELSE code END,CASE WHEN outcome='succeeded' THEN p_evidence_fingerprint ELSE NULL END,now_at); PERFORM control_plane.recompute_membership_access_operation(s.operation_id); RETURN true;
END $$;

CREATE FUNCTION control_plane.retry_membership_access_step(p_step_id uuid,p_blocked_attempt_id uuid,p_expected_generation bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane AS $$
DECLARE s membership_access_steps%ROWTYPE; a membership_access_step_attempts%ROWTYPE; now_at timestamptz; BEGIN
 SELECT * INTO s FROM membership_access_steps WHERE id=p_step_id FOR UPDATE; IF NOT FOUND OR s.step_kind LIKE '%_prerequisite' OR s.state<>'blocked' OR s.lease_generation<>p_expected_generation THEN RETURN false; END IF; PERFORM 1 FROM membership_access_operations WHERE id=s.operation_id FOR UPDATE; now_at:=clock_timestamp();
 SELECT * INTO a FROM membership_access_step_attempts WHERE id=p_blocked_attempt_id AND step_id=s.id AND event_kind='result' AND outcome='blocked' AND lease_generation=p_expected_generation AND id=(SELECT id FROM membership_access_step_attempts WHERE step_id=s.id AND event_kind='result' ORDER BY created_at DESC,id DESC LIMIT 1) FOR UPDATE; IF NOT FOUND THEN RETURN false; END IF;
 INSERT INTO membership_access_step_attempts(id,step_id,operation_id,mapping_id,transition_revision,event_kind,prior_attempt_id,created_at) VALUES(gen_random_uuid(),s.id,s.operation_id,s.mapping_id,s.transition_revision,'operator_retry',a.id,now_at);
 UPDATE membership_access_steps SET state='retry_wait',attempt_count=0,next_attempt_at=now_at,lease_generation=lease_generation+1,lease_token=NULL,lease_owner=NULL,lease_expires_at=NULL,error_code=NULL,confirmed_at=NULL,evidence_fingerprint=NULL WHERE id=s.id; PERFORM control_plane.recompute_membership_access_operation(s.operation_id); RETURN true;
END $$;
REVOKE ALL ON FUNCTION control_plane.recompute_membership_access_operation(uuid),control_plane.claim_membership_access_step(text,text[]),control_plane.record_membership_access_step_result(uuid,uuid,bigint,bytea,text,text,text,bytea),control_plane.retry_membership_access_step(uuid,uuid,bigint) FROM PUBLIC;
DO $$ BEGIN EXECUTE format('GRANT USAGE ON SCHEMA control_plane TO %I',current_setting('control_plane.revocation_role')); EXECUTE format('GRANT EXECUTE ON FUNCTION control_plane.claim_membership_access_step(text,text[]), control_plane.record_membership_access_step_result(uuid,uuid,bigint,bytea,text,text,text,bytea) TO %I',current_setting('control_plane.revocation_role')); END $$;
